{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2155-11-04 23:10:00",
      "speaker": "Doctor",
      "text": "Hi, I’m Dr. Lee, one of your transplant team doctors. You’re here for your kidney transplant, right?"
    },
    {
      "turn_number": 2,
      "time": "2155-11-04 23:10:30",
      "speaker": "Patient",
      "text": "Yes, that’s right. I’ve been waiting for this for a long time. I’m a little nervous."
    },
    {
      "turn_number": 3,
      "time": "2155-11-04 23:11:00",
      "speaker": "Doctor",
      "text": "That’s completely understandable. You’re in good hands. We’ll do some final blood work tonight and plan to take you to surgery tomorrow morning."
    },
    {
      "turn_number": 4,
      "time": "2155-11-04 23:11:30",
      "speaker": "Patient",
      "text": "Okay, that sounds good. Will I be okay during the surgery? I have atrial fibrillation and I’m on Coumadin."
    },
    {
      "turn_number": 5,
      "time": "2155-11-04 23:12:00",
      "speaker": "Doctor",
      "text": "We’ve reviewed your history. Your Coumadin was stopped as planned before surgery. We’ll monitor your heart closely. You’ve had episodes of fast heart rate before, so we’re prepared for that."
    },
    {
      "turn_number": 6,
      "time": "2155-11-04 23:12:30",
      "speaker": "Patient",
      "text": "Thank you. And my thyroid? I take levothyroxine every day."
    },
    {
      "turn_number": 7,
      "time": "2155-11-04 23:13:00",
      "speaker": "Doctor",
      "text": "Yes, we’ll keep you on your usual dose. We’ll check your thyroid levels during your stay just to be safe."
    },
    {
      "turn_number": 8,
      "time": "2155-11-05 13:00:00",
      "speaker": "Doctor",
      "text": "Hi, you’re back from surgery. Everything went smoothly. You had the kidney transplant and the hernia repair with mesh."
    },
    {
      "turn_number": 9,
      "time": "2155-11-05 13:00:30",
      "speaker": "Patient",
      "text": "Oh, good. Did the kidney start working?"
    },
    {
      "turn_number": 10,
      "time": "2155-11-05 13:01:00",
      "speaker": "Doctor",
      "text": "It had good color and blood flow, but it didn’t make urine right away. That can happen. We’ll keep monitoring it."
    },
    {
      "turn_number": 11,
      "time": "2155-11-05 13:01:30",
      "speaker": "Patient",
      "text": "I felt my heart racing earlier. Is that why I’m in the ICU?"
    },
    {
      "turn_number": 12,
      "time": "2155-11-05 13:02:00",
      "speaker": "Doctor",
      "text": "Yes, you were in atrial fibrillation with a fast heart rate. We gave you medication through your IV to help control it. You’re on amiodarone and metoprolol now, just like before."
    },
    {
      "turn_number": 13,
      "time": "2155-11-05 13:02:30",
      "speaker": "Patient",
      "text": "Okay. I’m feeling a little better now. What about my potassium? It’s always high."
    },
    {
      "turn_number": 14,
      "time": "2155-11-05 13:03:00",
      "speaker": "Doctor",
      "text": "Your potassium was high—6.7—so we did an emergency dialysis session last night. You’ll have another one today to keep it under control."
    },
    {
      "turn_number": 15,
      "time": "2155-11-05 13:03:30",
      "speaker": "Patient",
      "text": "Got it. Will I keep needing dialysis?"
    },
    {
      "turn_number": 16,
      "time": "2155-11-05 13:04:00",
      "speaker": "Doctor",
      "text": "For now, yes. We’re hoping the new kidney starts working soon. If it does, we’ll stop dialysis."
    },
    {
      "turn_number": 17,
      "time": "2155-11-06 09:00:00",
      "speaker": "Doctor",
      "text": "Good morning. Your heart rate is more stable today. We’re switching you from the IV amiodarone to your regular pill."
    },
    {
      "turn_number": 18,
      "time": "2155-11-06 09:00:30",
      "speaker": "Patient",
      "text": "That’s good. How’s the kidney doing?"
    },
    {
      "turn_number": 19,
      "time": "2155-11-06 09:01:00",
      "speaker": "Doctor",
      "text": "Still not making much urine—less than 50 cc in 24 hours. But the ultrasound showed good blood flow, no blockages. That’s a good sign."
    },
    {
      "turn_number": 20,
      "time": "2155-11-06 09:01:30",
      "speaker": "Patient",
      "text": "So it might just be slow to start?"
    },
    {
      "turn_number": 21,
      "time": "2155-11-06 09:02:00",
      "speaker": "Doctor",
      "text": "Exactly. We call that delayed graft function. It happens sometimes, especially with ECD kidneys. We’ll keep supporting you with dialysis for now."
    },
    {
      "turn_number": 22,
      "time": "2155-11-07 10:00:00",
      "speaker": "Doctor",
      "text": "You’re being moved to the regular floor today. Your heart rate stayed stable overnight."
    },
    {
      "turn_number": 23,
      "time": "2155-11-07 10:00:30",
      "speaker": "Patient",
      "text": "Great. I feel stronger. But I had some jaw pain and my arm felt heavy earlier."
    },
    {
      "turn_number": 24,
      "time": "2155-11-07 10:01:00",
      "speaker": "Doctor",
      "text": "We checked your EKG and enzymes. No sign of a heart attack. You were in atrial fibrillation again, but your rate is controlled. Cardiology recommends adding IV metoprolol when needed."
    },
    {
      "turn_number": 25,
      "time": "2155-11-07 10:01:30",
      "speaker": "Patient",
      "text": "I’m glad it wasn’t my heart. But I’m tired of being in AFib."
    },
    {
      "turn_number": 26,
      "time": "2155-11-07 10:02:00",
      "speaker": "Doctor",
      "text": "We are too. But as long as your rate is controlled and you’re not having chest pain, we’ll manage it with meds for now."
    },
    {
      "turn_number": 27,
      "time": "2155-11-08 09:30:00",
      "speaker": "Doctor",
      "text": "Your labs look stable. Potassium is 5.2. You’re still not making much urine, but your weight is up, so we’re watching your fluid balance."
    },
    {
      "turn_number": 28,
      "time": "2155-11-08 09:30:30",
      "speaker": "Patient",
      "text": "Is that bad—weight going up?"
    },
    {
      "turn_number": 29,
      "time": "2155-11-08 09:31:00",
      "speaker": "Doctor",
      "text": "Not necessarily. Since the kidney isn’t filtering yet, fluid builds up. But your breathing is fine, so we’re okay for now."
    },
    {
      "turn_number": 30,
      "time": "2155-11-09 08:45:00",
      "speaker": "Doctor",
      "text": "Big news—your urine output increased today! You made about 300 cc in 24 hours."
    },
    {
      "turn_number": 31,
      "time": "2155-11-09 08:45:30",
      "speaker": "Patient",
      "text": "Really? That’s a good sign, right?"
    },
    {
      "turn_number": 32,
      "time": "2155-11-09 08:46:00",
      "speaker": "Doctor",
      "text": "Yes! It means the kidney is starting to wake up. We’ll keep an eye on your creatinine and see if it starts to drop."
    },
    {
      "turn_number": 33,
      "time": "2155-11-10 09:00:00",
      "speaker": "Doctor",
      "text": "You made 500 cc of urine yesterday! Creatinine is still high, but stable. We’re not planning more dialysis unless needed."
    },
    {
      "turn_number": 34,
      "time": "2155-11-10 09:00:30",
      "speaker": "Patient",
      "text": "That’s amazing. When will I know if the kidney is really working?"
    },
    {
      "turn_number": 35,
      "time": "2155-11-10 09:01:00",
      "speaker": "Doctor",
      "text": "We’ll know more in the next few days. If output keeps rising and creatinine drops, we’ll be confident it’s functioning."
    },
    {
      "turn_number": 36,
      "time": "2155-11-11 10:15:00",
      "speaker": "Doctor",
      "text": "You made 750 cc of urine yesterday! Creatinine is 6.5—still high, but not rising. This is a great step forward."
    },
    {
      "turn_number": 37,
      "time": "2155-11-11 10:15:30",
      "speaker": "Patient",
      "text": "I can’t believe it. I’m so relieved. What about my meds?"
    },
    {
      "turn_number": 38,
      "time": "2155-11-11 10:16:00",
      "speaker": "Doctor",
      "text": "Your tacrolimus level was 11.6, which is a bit high, so we lowered the dose to 5 mg twice a day."
    },
    {
      "turn_number": 39,
      "time": "2155-11-11 10:16:30",
      "speaker": "Patient",
      "text": "And the Cellcept? It’s been giving me heartburn."
    },
    {
      "turn_number": 40,
      "time": "2155-11-11 10:17:00",
      "speaker": "Doctor",
      "text": "We switched you to Myfortic. It’s similar but easier on the stomach. You’ve been tolerating it well."
    },
    {
      "turn_number": 41,
      "time": "2155-11-11 10:17:30",
      "speaker": "Patient",
      "text": "Thank you. Can I restart my Coumadin? I’m worried about clots."
    },
    {
      "turn_number": 42,
      "time": "2155-11-11 10:18:00",
      "speaker": "Doctor",
      "text": "Yes, we’re restarting warfarin tonight. Since the kidney is making urine, we don’t need to worry about a biopsy, so it’s safe to restart."
    },
    {
      "turn_number": 43,
      "time": "2155-11-11 10:18:30",
      "speaker": "Patient",
      "text": "Good. And my thyroid? You said you checked it."
    },
    {
      "turn_number": 44,
      "time": "2155-11-11 10:19:00",
      "speaker": "Doctor",
      "text": "Your TSH is low—0.2—but your free T4 is normal. It might be from the amiodarone. Keep taking your levothyroxine and follow up with your PCP after discharge."
    },
    {
      "turn_number": 45,
      "time": "2155-11-12 09:00:00",
      "speaker": "Doctor",
      "text": "You’re doing well. You’ve had bowel movements, you’re eating regular food—just low potassium for now."
    },
    {
      "turn_number": 46,
      "time": "2155-11-12 09:00:30",
      "speaker": "Patient",
      "text": "No bananas or potatoes, right?"
    },
    {
      "turn_number": 47,
      "time": "2155-11-12 09:01:00",
      "speaker": "Doctor",
      "text": "Exactly. Avoid tomatoes, oranges, and dark greens too. Drink plenty of fluids so your urine stays light yellow."
    },
    {
      "turn_number": 48,
      "time": "2155-11-12 09:01:30",
      "speaker": "Patient",
      "text": "Got it. When can I go home?"
    },
    {
      "turn_number": 49,
      "time": "2155-11-12 09:02:00",
      "speaker": "Doctor",
      "text": "If all goes well, tomorrow. We’ll make sure your pain is controlled and your labs are stable."
    },
    {
      "turn_number": 50,
      "time": "2155-11-13 08:00:00",
      "speaker": "Doctor",
      "text": "Good news—you’re cleared to go home today."
    },
    {
      "turn_number": 51,
      "time": "2155-11-13 08:00:30",
      "speaker": "Patient",
      "text": "That’s wonderful! What do I need to do when I get home?"
    },
    {
      "turn_number": 52,
      "time": "2155-11-13 08:01:00",
      "speaker": "Doctor",
      "text": "Take all your meds as prescribed. You’ll get Myfortic, tacrolimus, warfarin, and others. Check your urine output daily."
    },
    {
      "turn_number": 53,
      "time": "2155-11-13 08:01:30",
      "speaker": "Patient",
      "text": "And the oxycodone for pain?"
    },
    {
      "turn_number": 54,
      "time": "2155-11-13 08:02:00",
      "speaker": "Doctor",
      "text": "Only as needed. Don’t drive while taking it. And no lifting more than 5 pounds for several weeks."
    },
    {
      "turn_number": 55,
      "time": "2155-11-13 08:02:30",
      "speaker": "Patient",
      "text": "What about my incision?"
    },
    {
      "turn_number": 56,
      "time": "2155-11-13 08:03:00",
      "speaker": "Doctor",
      "text": "You can shower—just pat it dry. No lotions. Watch for redness, drainage, or fever. Call the clinic if any of that happens."
    },
    {
      "turn_number": 57,
      "time": "2155-11-13 08:03:30",
      "speaker": "Patient",
      "text": "And labs?"
    },
    {
      "turn_number": 58,
      "time": "2155-11-13 08:04:00",
      "speaker": "Doctor",
      "text": "Blood work every Monday and Thursday—CBC, chem panel, tacrolimus level. Send results to the transplant clinic. INR goes to your PCP."
    },
    {
      "turn_number": 59,
      "time": "2155-11-13 08:04:30",
      "speaker": "Patient",
      "text": "I’ll make sure to do that. Thank you for everything."
    },
    {
      "turn_number": 60,
      "time": "2155-11-13 08:05:00",
      "speaker": "Doctor",
      "text": "You did great. The kidney is starting to work, and you’re on the right track. Call us with any concerns."
    },
    {
      "turn_number": 61,
      "time": "2155-11-13 08:05:30",
      "speaker": "Patient",
      "text": "I will. I’m just so grateful."
    },
    {
      "turn_number": 62,
      "time": "2155-11-13 08:06:00",
      "speaker": "Doctor",
      "text": "We’re glad to see you doing well. Take care, and we’ll see you in clinic soon."
    },
    {
      "turn_number": 63,
      "time": "2155-11-13 08:06:30",
      "speaker": "Patient",
      "text": "Thank you, Doctor."
    },
    {
      "turn_number": 64,
      "time": "2155-11-13 08:07:00",
      "speaker": "Doctor",
      "text": "One more thing—your nystatin is for a possible mouth infection. Use it four times a day as directed."
    },
    {
      "turn_number": 65,
      "time": "2155-11-13 08:07:30",
      "speaker": "Patient",
      "text": "Okay, I’ll start that today."
    },
    {
      "turn_number": 66,
      "time": "2155-11-13 08:08:00",
      "speaker": "Doctor",
      "text": "And the docusate—just to help with constipation from the pain meds."
    },
    {
      "turn_number": 67,
      "time": "2155-11-13 08:08:30",
      "speaker": "Patient",
      "text": "Got it. I’ll take it twice a day."
    },
    {
      "turn_number": 68,
      "time": "2155-11-13 08:09:00",
      "speaker": "Doctor",
      "text": "You’re all set. The nurse will go over your discharge papers and get you on your way."
    },
    {
      "turn_number": 69,
      "time": "2155-11-13 08:09:30",
      "speaker": "Patient",
      "text": "Thank you again. I’m ready to go home."
    },
    {
      "turn_number": 70,
      "time": "2155-11-13 08:10:00",
      "speaker": "Doctor",
      "text": "You’ve made great progress. Keep following up, and take it easy."
    },
    {
      "turn_number": 71,
      "time": "2155-11-13 08:10:30",
      "speaker": "Patient",
      "text": "I will. I’m so thankful for the new kidney."
    },
    {
      "turn_number": 72,
      "time": "2155-11-13 08:11:00",
      "speaker": "Doctor",
      "text": "We’re hopeful it will keep improving. Call us if anything changes."
    },
    {
      "turn_number": 73,
      "time": "2155-11-13 08:11:30",
      "speaker": "Patient",
      "text": "I will. Thanks for all your care."
    },
    {
      "turn_number": 74,
      "time": "2155-11-13 08:12:00",
      "speaker": "Doctor",
      "text": "You’re very welcome. Have a safe trip home."
    },
    {
      "turn_number": 75,
      "time": "2155-11-13 08:12:30",
      "speaker": "Patient",
      "text": "I will. See you soon."
    },
    {
      "turn_number": 76,
      "time": "2155-11-13 08:13:00",
      "speaker": "Doctor",
      "text": "Take care."
    },
    {
      "turn_number": 77,
      "time": "2155-11-13 08:13:30",
      "speaker": "Patient",
      "text": "Bye."
    },
    {
      "turn_number": 78,
      "time": "2155-11-13 08:14:00",
      "speaker": "Doctor",
      "text": "Goodbye."
    },
    {
      "turn_number": 79,
      "time": "2155-11-13 08:14:30",
      "speaker": "Patient",
      "text": "Thank you."
    },
    {
      "turn_number": 80,
      "time": "2155-11-13 08:15:00",
      "speaker": "Doctor",
      "text": "You’re welcome."
    },
    {
      "turn_number": 81,
      "time": "2155-11-13 08:15:30",
      "speaker": "Patient",
      "text": "I’ll call if I have any problems."
    },
    {
      "turn_number": 82,
      "time": "2155-11-13 08:16:00",
      "speaker": "Doctor",
      "text": "Please do. We’re here for you."
    },
    {
      "turn_number": 83,
      "time": "2155-11-13 08:16:30",
      "speaker": "Patient",
      "text": "I appreciate that."
    },
    {
      "turn_number": 84,
      "time": "2155-11-13 08:17:00",
      "speaker": "Doctor",
      "text": "Take it one day at a time."
    },
    {
      "turn_number": 85,
      "time": "2155-11-13 08:17:30",
      "speaker": "Patient",
      "text": "I will. Thank you."
    }
  ],
  "summary": {
    "admission_start": "2155-11-04 23:10:00",
    "admission_end": "2155-11-13 15:20:00",
    "summary_paragraph": "The patient was admitted for a kidney transplant due to end-stage renal disease from polycystic kidney disease. She underwent an ECD kidney transplant and ventral hernia repair with mesh. Postoperatively, she developed atrial fibrillation with rapid ventricular response and hyperkalemia, requiring ICU admission and emergent dialysis. The transplanted kidney initially showed delayed graft function with minimal urine output, but by postoperative day 7, urine output improved to 750 cc without dialysis, and creatinine stabilized. Immunosuppressive therapy was initiated with tacrolimus, mycophenolate (switched from Cellcept to Myfortic due to heartburn), and steroids. Warfarin was restarted prior to discharge. She was discharged home in stable condition with instructions for medication management, lab monitoring, and activity restrictions.",
    "problems": [
      "Hypertensive chronic kidney disease, unspecified, with chronic kidney disease stage V or end stage renal disease",
      "End stage renal disease",
      "Polycystic kidney, unspecified type",
      "Incisional hernia without mention of obstruction or gangrene",
      "Renal dialysis status",
      "Atrial fibrillation",
      "Anemia, unspecified",
      "Unspecified acquired hypothyroidism",
      "Long-term (current) use of anticoagulants"
    ]
  }
}
